entries[289913] = { ["name"] = "Bwonsamdis Pakt", ["text"] = "Sofort 15 sek. Abklingzeit\nVerflucht einen Spielercharakter und fügt ihm 20 Schattenschaden zu. Wenn es dem Spielercharakter nicht innerhalb von 15 Sek. gelingt, einen Spielercharakter in der Nähe mit Bwonsamdis Messer zu stechen, erleidet er 500 Schattenschaden.\n\nWenn es ihm gelingt, werden beide Spielercharaktere mit 'Bwonsamdis Pakt' belegt, wodurch sie stattdessen alle 3 Sek. 15 Schattenschaden erleiden." }
entries[289914] = { ["name"] = "Bwonsamdis Pakt", ["text"] = "100 Meter Reichweite\nWirken in 2.5 sek.\nVerflucht einen Spielercharakter und fügt ihm 4362 Schattenschaden zu. Wenn es dem Spielercharakter nicht innerhalb von 15 Sek. gelingt, einen Spielercharakter in der Nähe mit Bwonsamdis Messer zu stechen, erleidet er 109041 Schattenschaden.\n\nWenn es ihm gelingt, werden beide Spielercharaktere mit 'Bwonsamdis Pakt' belegt, wodurch sie stattdessen alle 3 Sek. 3274 Schattenschaden erleiden." }
entries[289915] = { ["name"] = "Sengende Detonation", ["text"] = "200 Meter Reichweite\nWirken in 1 sek.\nKönig Rastakhan kanalisiert Feuer auf einen Gegner und fügt ihm 5 Sek. lang alle 1 Sek. 5452 Feuerschaden zu. Bei Ende der Kanalisierung explodiert das Ziel und erleidet 26170 Feuerschaden. Dieser Schaden verringert sich mit steigender Entfernung des Primärziels zu König Rastakhan." }
